const retryChannelNotificationDelivery = `-- name: RetryChannelNotificationDelivery :execrows
UPDATE channel_notification_delivery
SET status = CASE WHEN attempt_count >= $1 THEN 'dead' ELSE 'pending' END,
    next_attempt_at = $2,
    lease_token = NULL,
    lease_expires_at = NULL,
    last_error_code = $3,
    updated_at = now()
WHERE id = $4
  AND status = 'sending'
  AND lease_token = $5
`

type RetryChannelNotificationDeliveryParams struct {
	MaxAttempts   int32              `json:"max_attempts"`
	NextAttemptAt pgtype.Timestamptz `json:"next_attempt_at"`
	LastErrorCode pgtype.Text        `json:"last_error_code"`
	ID            pgtype.UUID        `json:"id"`
	LeaseToken    pgtype.UUID        `json:"lease_token"`
}

func (q *Queries) RetryChannelNotificationDelivery(ctx context.Context, arg RetryChannelNotificationDeliveryParams) (int64, error) {
	result, err := q.db.Exec(ctx, retryChannelNotificationDelivery,
		arg.MaxAttempts,
		arg.NextAttemptAt,
		arg.LastErrorCode,
		arg.ID,
		arg.LeaseToken,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

